export function TodayApp() {
  const todos = signal<Todo[]>([/* three todos */])
  const draft = signal('')
  const left = computed(() => todos().filter((t) => !t.done).length)
  const add = () => { /* push draft(), clear it */ }

  return (
    <Stack gap={4}>
      <Inline align="center">
        <Text size="xl" weight="bold">Today</Text>
        <Text size="sm">{`${left()} left`}</Text>
      </Inline>
      <Field value={draft} onChangeText={(t) => draft.set(t)} onSubmit={add} />
      <For each={todos} by={(t) => t.id}>
        {(t) => <TodoRow todo={t} onToggle={() => toggle(t.id)} onRemove={() => remove(t.id)} />}
      </For>
    </Stack>
  )
}

